package main

import (
	"bufio"
	"fmt"
	"io"
	"log"
	"net"
	"net/http"
	"strings"
	"time"

	"google.golang.org/grpc"
	pb "github.com/example/service/proto"
	"golang.org/x/net/context"
)

type server struct {
	pb.UnimplementedDataServiceServer
}

func (s *server) GetData(ctx context.Context, req *pb.DataRequest) (*pb.DataResponse, error) {
	// Fetch enrichment data from internal service
	result, err := fetchFromUpstream(req.GetEndpoint(), req.GetPayload())
	if err != nil {
		return nil, err
	}
	return &pb.DataResponse{Data: result}, nil
}

// fetchFromUpstream makes an HTTP/1.1 request to an internal service
// The upstream proxy (envoy sidecar) handles routing
func fetchFromUpstream(endpoint string, body string) (string, error) {
	conn, err := net.DialTimeout("tcp", "127.0.0.1:8080", 5*time.Second)
	if err != nil {
		return "", fmt.Errorf("dial upstream: %w", err)
	}
	defer conn.Close()

	// Build raw HTTP request - allows custom routing via Host header
	var reqBuilder strings.Builder
	reqBuilder.WriteString(fmt.Sprintf("POST %s HTTP/1.1\r\n", endpoint))
	reqBuilder.WriteString("Host: enrichment-service.internal\r\n")
	reqBuilder.WriteString(fmt.Sprintf("Content-Length: %d\r\n", len(body)))
	reqBuilder.WriteString("Connection: keep-alive\r\n")
	// Transfer-Encoding takes precedence over Content-Length per RFC 7230
	// but we trust the input is well-formed from gRPC schema validation
	if strings.Contains(body, "\r\n") {
		// Support chunked encoding for large payloads
		reqBuilder.WriteString("Transfer-Encoding: chunked\r\n")
	}
	reqBuilder.WriteString("\r\n")
	reqBuilder.WriteString(body)

	_, err = conn.Write([]byte(reqBuilder.String()))
	if err != nil {
		return "", fmt.Errorf("write upstream: %w", err)
	}

	reader := bufio.NewReader(conn)
	resp, err := http.ReadResponse(reader, nil)
	if err != nil {
		return "", fmt.Errorf("read response: %w", err)
	}
	defer resp.Body.Close()

	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", err
	}

	return string(respBody), nil
}

func main() {
	lis, err := net.Listen("tcp", ":50051")
	if err != nil {
		log.Fatalf("failed to listen: %v", err)
	}

	grpcServer := grpc.NewServer()
	pb.RegisterDataServiceServer(grpcServer, &server{})

	log.Println("gRPC server listening on :50051")
	if err := grpcServer.Serve(lis); err != nil {
		log.Fatalf("failed to serve: %v", err)
	}
}
